<script>
(function(){
var $=function(i){return document.getElementById(i)},ls=function(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(e){return null}},ss=function(k,v){try{if(v===undefined)return sessionStorage.getItem(k);sessionStorage.setItem(k,v)}catch(e){return null}};
var ua=navigator.userAgent||'',isIOS=/iPhone|iPad|iPod/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
var standalone=function(){return (window.matchMedia&&matchMedia('(display-mode: standalone)').matches)||navigator.standalone===true};
var dp=null;
window.DFPWA={isIOS:isIOS,standalone:standalone,installed:function(){return standalone()||ls('dfInstalled')==='1'},canPrompt:function(){return !!dp}};
function open(id){var m=$(id);if(m)m.classList.add('on')}
document.querySelectorAll('.dfm [data-x]').forEach(function(b){b.addEventListener('click',function(){b.closest('.dfm').classList.remove('on')})});
var isAnd=/Android/i.test(ua);
function paint(){var inst=standalone()||ls('dfInstalled')==='1';document.querySelectorAll('#dfapp [data-pwa]').forEach(function(b){var k=b.getAttribute('data-pwa'),mine=k==='ios'?isIOS:!isIOS,l=b.querySelector('[data-l]');
 if(isIOS&&k==='android'||isAnd&&k==='ios')b.style.display='none';else b.style.display='';
 if(l)l.textContent=(inst&&mine)?'Installed ✓ — Open / Reinstall':(k==='ios'?'Install for iPhone':'Install for Android')})}
function setInstalledUI(){paint();var f=$('dfapp');if(f)f.classList.add('done');var p=$('dfi');if(p)p.classList.remove('on');var q=$('dfs');if(q)q.classList.remove('on');document.querySelectorAll('.df-hide-inst').forEach(function(e){e.style.display='none'});document.querySelectorAll('.df-show-inst').forEach(function(e){e.style.display=''});document.dispatchEvent(new Event('dfpwa:installed'))}
function install(kind){
  if(standalone()){open('dfm-open');return}
  if(dp){ls('dfInstalled','0');paint();var e=dp;dp=null;e.prompt();e.userChoice.then(function(c){if(c&&c.outcome==='accepted'){ls('dfInstalled','1');setInstalledUI();if(window.DFPWA.rewardPopup)window.DFPWA.rewardPopup()}})['catch'](function(){});return}
  if(ls('dfInstalled')==='1'&&((kind==='ios')===isIOS)){open('dfm-open');return}
  if(isIOS||kind==='ios'){open('dfm-ios');return}
  open('dfm-gen')
}
window.DFPWA.install=install;
document.querySelectorAll('[data-pwa]').forEach(function(b){b.addEventListener('click',function(){install(b.getAttribute('data-pwa'))})});
addEventListener('beforeinstallprompt',function(e){e.preventDefault();dp=e;if(ls('dfInstalled')==='1'){ls('dfInstalled','0');paint()}schedule()});
if($('dfm-re'))$('dfm-re').addEventListener('click',function(){ls('dfInstalled','0');paint();var m=$('dfm-open');if(m)m.classList.remove('on');install(isIOS?'ios':'android')});
paint();
addEventListener('appinstalled',function(){ls('dfInstalled','1');dp=null;setInstalledUI()});
if(standalone()||ls('dfInstalled')==='1')setInstalledUI();
// App Install reward: the page marks this browser as "the App" (cookie df_app) only while it runs as the installed app, so the reward applies to App orders only; the install is recorded once and a logged-in customer with a verified mobile unlocks the reward.
function ckSet(n,v){document.cookie=n+'='+v+';path=/;max-age='+(400*86400)+';SameSite=Lax;Secure'}
function ckDel(n){document.cookie=n+'=;path=/;max-age=0;SameSite=Lax;Secure'}
function iid(){var v=ls('dfInstallId');if(!v||!/^[A-Za-z0-9-]{16,48}$/.test(v)){try{v=crypto.randomUUID()}catch(e){v=''}if(!v)v=(Date.now().toString(36)+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2)+'0000000000000000').slice(0,32);ls('dfInstallId',v)}return v}
function rwToast(t){var d=document.createElement('div');d.setAttribute('role','status');d.style.cssText='position:fixed;left:50%;top:14px;transform:translateX(-50%);z-index:2147481600;max-width:92vw;background:#0B1220;color:#fff;border-radius:14px;padding:12px 16px;font-size:14px;font-weight:600;box-shadow:0 12px 30px rgba(11,18,32,.35);border:1px solid #FF8A3D';d.textContent=t;document.body.appendChild(d);setTimeout(function(){d.remove()},7000)}
function appSend(){
  fetch('/account/app-activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:iid()}),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){
    if(!j||!j.ok)return;if(j.unlocked||(!j.login&&!j.verify))ss('dfActOk','1');
    if(j.on&&!j.unlocked&&(j.login||j.verify)&&standalone()){var t=+ls('dfRwPop2')||0;if(!t||Date.now()-t>864e5){ls('dfRwPop2',String(Date.now()));setTimeout(function(){rwShow('welcome',Math.round(j.amount),j)},1500)}}
    if(j.unlocked&&j.status==='available'&&!ls('dfRwToast')){ls('dfRwToast','1');rwToast('🎁 ৳'+Math.round(j.amount)+' App Install Reward unlocked — প্রথম App অর্ডারে অটো ছাড় পাবেন')}
  })['catch'](function(){});
}

// install popup: promise the reward only while the rule is ON
var rwInfo=null;function rwGet(cb){if(rwInfo){cb(rwInfo);return}fetch('/account/app-reward',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){rwInfo=j;cb(j)})['catch'](function(){})}
function rwShow(kind,amt,j){var m=$('dfm-rw');if(!m)return;var t=$('rwp-t'),p=$('rwp-p'),o=$('rwp-o'),go=$('rwp-go'),ok=$('rwp-ok');go.style.display='none';ok.classList.remove('sec');
  if(kind==='install'){t.innerHTML='অ্যাপ ইনস্টল করছেন? <b>৳'+amt+' ডিসকাউন্ট</b> আপনার!';p.textContent='আপনার ডাউনলোড সম্পূর্ণ হলেই প্রথম অ্যাপ অর্ডারে ৳'+amt+' ছাড় পাবেন — কুপন কোড লাগবে না, অটো যুক্ত হবে।';
    o.innerHTML='<li><span>1</span><div>অ্যাপটি ইনস্টল হতে দিন ও <b>খুলুন</b></div></li><li><span>2</span><div><b>লগইন</b> করে মোবাইল নম্বর <b>ভেরিফাই</b> করুন</div></li><li><span>3</span><div>প্রথম অর্ডারে <b>৳'+amt+'</b> অটো কেটে যাবে</div></li>';ok.textContent='ঠিক আছে, বুঝেছি'}
  else{var lg=j&&j.login;t.innerHTML='স্বাগতম! 🎉 <b>৳'+amt+'</b> রিওয়ার্ড অপেক্ষা করছে';p.textContent=lg?'লগইন করে আপনার মোবাইল নম্বর ভেরিফাই করুন — প্রথম অ্যাপ অর্ডারে ৳'+amt+' ছাড় অটো পাবেন।':'আপনার মোবাইল নম্বর ভেরিফাই করলেই প্রথম অ্যাপ অর্ডারে ৳'+amt+' ছাড় অটো যুক্ত হবে।';o.innerHTML='';go.href=lg?'/account/login':'/account/profile';go.textContent=lg?'লগইন করুন':'মোবাইল ভেরিফাই করুন';go.style.display='block';ok.textContent='পরে করব';ok.classList.add('sec')}
  m.classList.add('on')}
document.querySelectorAll('#dfm-rw [data-x]').forEach(function(b){b.addEventListener('click',function(){$('dfm-rw').classList.remove('on')})});
function rwInstallPop(){if(ls('dfRwPop1'))return;rwGet(function(i){if(i&&i.on){ls('dfRwPop1','1');rwShow('install',i.amt)}})}
window.DFPWA.rewardPopup=rwInstallPop;
function appBeat(){if(!standalone()||document.hidden)return;fetch('/account/app-activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:iid(),beat:1}),credentials:'same-origin',keepalive:true})['catch'](function(){})}
function appSync(){if(standalone()){ckSet('df_app',iid());if(!ss('dfActOk'))appSend();else appBeat();if(!window.__dfBeat){window.__dfBeat=setInterval(appBeat,60000);document.addEventListener('visibilitychange',function(){if(!document.hidden)appBeat()})}}else{ckDel('df_app')}}
appSync();
addEventListener('appinstalled',function(){setTimeout(appSend,400);setTimeout(rwInstallPop,600)});
// polite install popup: after a bit of browsing, once per session, not again for 7 days after "Not Now"
var shown=false;
function schedule(){
  if(shown||standalone()||ls('dfInstalled')==='1'||ss('dfiHide'))return;var t=+ls('dfiNo')||0;if(t&&Date.now()-t<7*864e5)return;
  var n=(+ss('dfPv')||0);var delay=n>=2?3000:15000;
  setTimeout(function(){if(shown||ss('dfiHide')||(!dp&&!isIOS))return;shown=true;(innerWidth<=760?$('dfs'):$('dfi')).classList.add('on')},innerWidth<=760?Math.min(delay,8000):delay)}
ss('dfPv',String((+ss('dfPv')||0)+1));
if(isIOS)schedule();
function hide(){$('dfi').classList.remove('on');$('dfs').classList.remove('on');ss('dfiHide','1')}
$('dfs-x').onclick=hide;$('dfs-go').onclick=function(){hide();install('auto')};
$('dfi-no').onclick=function(){ls('dfiNo',String(Date.now()));hide()};$('dfi-no0').onclick=$('dfi-no').onclick;
$('dfi-go').onclick=function(){hide();install('auto')};

// push notifications
function pSup(){return 'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window}
function u8(b){var p='='.repeat((4-b.length%4)%4),s=(b+p).replace(/-/g,'+').replace(/_/g,'/'),r=atob(s),o=new Uint8Array(r.length);for(var i=0;i<r.length;i++)o[i]=r.charCodeAt(i);return o}
function pSend(s){return fetch('/push/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(s.toJSON()),credentials:'same-origin'})}
window.DFPWA.pushOn=function(){if(!pSup())return Promise.resolve(false);return Notification.requestPermission().then(function(p){if(p!=='granted')return false;return navigator.serviceWorker.ready.then(function(reg){return fetch('/push/key').then(function(r){return r.json()}).then(function(k){return reg.pushManager.getSubscription().then(function(s){return s||reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:u8(k.key)})})}).then(function(s){return pSend(s).then(function(){return true})})})})['catch'](function(){return false})};
window.DFPWA.pushOff=function(){return navigator.serviceWorker.ready.then(function(reg){return reg.pushManager.getSubscription().then(function(s){if(!s)return;return fetch('/push/unsubscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({endpoint:s.endpoint})}).then(function(){return s.unsubscribe()})})})};
if(pSup()&&Notification.permission==='granted'&&!ss('dfPs')){ss('dfPs','1');navigator.serviceWorker.ready.then(function(reg){return reg.pushManager.getSubscription()}).then(function(s){if(s)pSend(s)})['catch'](function(){})}
function nSchedule(){
  if(!pSup()||Notification.permission!=='default'||ss('dfnHide'))return;if(!(standalone()||ls('dfInstalled')==='1'))return;var t=+ls('dfnNo')||0;if(t&&Date.now()-t<14*864e5)return;
  if((+ss('dfPv')||0)<2)return;setTimeout(function(){if(ss('dfnHide')||$('dfi').classList.contains('on')||$('dfs').classList.contains('on'))return;$('dfn').classList.add('on')},6000)}
nSchedule();
function nHide(){$('dfn').classList.remove('on');ss('dfnHide','1')}
$('dfn-no').onclick=function(){ls('dfnNo',String(Date.now()));nHide()};$('dfn-no0').onclick=$('dfn-no').onclick;
$('dfn-go').onclick=function(){nHide();window.DFPWA.pushOn()};
// service worker + update prompt
if('serviceWorker' in navigator){addEventListener('load',function(){navigator.serviceWorker.register('/pwa-sw').then(function(reg){
  function ready(w){if(!navigator.serviceWorker.controller)return;window.DFPWA_UPDATE=function(){w.postMessage('SKIP_WAITING')}} /* silent: new version installs in the background and is used on the next normal open; no popup */
  if(reg.waiting)ready(reg.waiting);
  reg.addEventListener('updatefound',function(){var w=reg.installing;if(!w)return;w.addEventListener('statechange',function(){if(w.state==='installed')ready(w)})});
  setInterval(function(){reg.update()['catch'](function(){})},3600000);
})['catch'](function(){});var r=false;navigator.serviceWorker.addEventListener('controllerchange',function(){if(r)return;r=true;location.reload()})})}
// notification bell
(function(){var b=$('dfb'),pn=$('dfbp'),n=$('dfbn');if(!b||!pn)return;var IC={offers:'🔥',coupons:'🎟',membership:'⭐',delivery:'🚚',support:'💬',orders:'📦'};
function esc(t){return String(t==null?'':t).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
function pushable(){return 'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window&&Notification.permission==='default'}
function paint(j){var u=j.unread||0;n.textContent=u>9?'9+':u;n.style.display=u?'block':'none';
 var h=!j.auth?'<div class="dfp-e">নোটিফিকেশন দেখতে <a href="/account" style="color:#FF5A00;font-weight:700">লগইন করুন</a>।</div>':(j.items.length?j.items.map(function(i){return '<a class="dfp-i '+(i.read?'':'un')+'" data-id="'+i.id+'" href="'+esc(i.url)+'"><i>'+(IC[i.cat]||'📦')+'</i><div><b>'+esc(i.title)+'</b>'+esc(i.body)+'<small>'+esc(i.ago)+'</small></div></a>'}).join(''):'<div class="dfp-e">কোনো নোটিফিকেশন নেই।</div>');
 $('dfp-l').innerHTML=h;$('dfp-all').style.display=(j.auth&&u)?'':'none';$('dfp-en').style.display=pushable()?'':'none'}
function load(){fetch('/push/bell',{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(paint)['catch'](function(){})}
b.addEventListener('click',function(e){e.stopPropagation();pn.classList.toggle('on');if(pn.classList.contains('on'))load()});
document.addEventListener('click',function(e){if(!pn.contains(e.target))pn.classList.remove('on')});
$('dfp-l').addEventListener('click',function(e){var a=e.target.closest('.dfp-i.un');if(a&&navigator.sendBeacon)navigator.sendBeacon('/push/read',new Blob([JSON.stringify({id:a.dataset.id})],{type:'application/json'}))});
$('dfp-all').onclick=function(){fetch('/push/read',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:'all'}),credentials:'same-origin'}).then(load)};
$('dfp-en').onclick=function(){window.DFPWA.pushOn().then(function(){load()})};
setTimeout(load,1200);setInterval(function(){if(!document.hidden)load()},60000);})();
})();
</script>
